Let $K \in \mathbb{Z}^{+}$ be arbitrary. Then
    \begin{equation}
        \begin{split}
            \sup_{\mkern-10mu \frac{N}{\log^b{N}} \leqslant \xi < \frac{N}{2}} &\biggl\lvert\mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\frac{\xi\left\lfloor m^c \right\rfloor}{N} \biggr) \biggr\rvert\\
            &\qquad \leqslant \;\;\smashoperator[l]{\sup_{\mkern-10mu \frac{N}{\log^b{N}} \leqslant \xi < \frac{N}{2}}} \Biggl\lvert \frac{100}{\gamma} \biggl(\frac{1}{K} + \sum_{k = 1}^{K} \frac{\bigl\lvert \hat{\mu}_1(k) \bigr\rvert + \bigl\lvert \hat{\mu}_2(k) \bigr\rvert  + \bigl\lvert \hat{\mu}_3(k) \bigr\rvert}{k} \biggr) + 4\pi\frac{\xi}{N} \gamma \Biggr\rvert.
        \end{split}
    \end{equation}

Let $q$ be a non-negative integer and $f$ be a function with $q + 2$ continuous derivatives on the interval $I \subseteq [X, 2X]$. Assume that there are constants $B_1, B_2$, and $F$ such that 
    \begin{equation}
        B_1 F X^{-r} \leqslant \lvert f^{(r)}(x)\rvert \leqslant B_2 F X^{-r}
    \end{equation} 
    for all $1 \leqslant r \leqslant q + 2$. Then there is a constant $B = B(B_1,B_2)$ such that 
    \[
        \biggl\lvert \sum_{n \in I} \mathrm{e}\bigl(f(n) \bigr) \biggr\rvert 
        \leqslant B \biggl(F^\frac{1}{2^{q+2}-2}X^{1-\frac{q+2}{2^{q+2}-2}} + \frac{X}{F} \biggr).
    \]

For $k \geqslant 1$,
    \begin{equation*}
        \bigl\lvert \hat{\mu}_1(k) \bigr\rvert, \bigl\lvert \hat{\mu}_2(k) \bigr\rvert 
        \leqslant 2\Biggl(\biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\Bigl(k - \frac{\xi}{N} \Bigr) m^c \biggr) \biggr\rvert 
        + \biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\Bigl(k + \frac{\xi}{N} \Bigr)m^c \Bigr) \biggr)\biggr\rvert + \bigl\lvert \hat{\mu}_3(k) \bigr\rvert \Biggr).
    \end{equation*}

Let $\mu$ be defined as in 3.9. Then,
    \begin{equation}
        \begin{split}
             \biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} &\textbf{1}_{P}\bigl(\{m^c\}\bigr) \mathrm{e}\biggl(\! -\frac{\xi}{N} m^c \biggr) \biggr\rvert\\
             &\leqslant 5\Bigl(\bigl\lvert \mu_1(P) - \mathrm{Leb}(P) \bigr\rvert + \bigl\lvert \mu_2(P) - \mathrm{Leb}(P) \bigr\rvert + \bigl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \delta_{\{m^c\}}(P) - \mathrm{Leb}(P) \bigr\rvert \Bigr).
         \end{split}
     \end{equation}

Define the measures
    \begin{align*}
        &\mu = \!\! \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi}{N} m^c \biggr) \delta_{\{m^c\}},\\ 
        &\mu_1 = \frac{1}{1 + c_1}\mathop{\mathbb{E}}_{m\leqslant M} \biggl(1 + \cos\biggl(\! -\frac{2 \pi i \xi m^c}{N} \biggr) \biggr)\delta_{\{m^c\}},\\
        &\mu_2 = \frac{1}{1 + c_2}\mathop{\mathbb{E}}_{m \leqslant M}\biggl(1 + \sin\biggl(\! -\frac{2 \pi i \xi m^c}{N}\biggr)\biggr)\delta_{\{m^c\}}, \text{ and } \\
        &\mu_3 = \!\! \mathop{\mathbb{E}}_{m \leqslant M} \delta_{\{m^c\}},
    \end{align*}
    where
    \begin{equation*}
        c_1 = \!\! \mathop{\mathbb{E}}_{m \leqslant M} \cos\biggl(\! -\frac{2\pi i \xi m^c}{N} \biggr) \text{ and } 
        c_2 = \!\! \mathop{\mathbb{E}}_{m \leqslant M} \sin\biggl(\! -\frac{2\pi i \xi m^c}{N}\biggr).
    \end{equation*}
    Then
    \begin{equation*}
        \lvert \mu(P) \rvert \leqslant 5 \Bigl(\bigl\lvert \mu_1(P) - \mathrm{Leb}(P) \bigr\rvert +  \bigl\lvert \mu_2(P) - \mathrm{Leb}(P) \bigr\rvert + \bigl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \delta_{\{m^c\}}(P) - \mathrm{Leb}(P) \bigr\rvert \Bigr).
    \end{equation*}
